def edge_set(net):
    """无向边集合（id 对，规范化 (min,max)）。"""
    edges = set()
    for e in net.edges():
        v1, v2 = net.edge_vertices(e)
        if v1 < v2:
            edges.add((v1, v2))
        else:
            edges.add((v2, v1))
    return edges
```

