def seed_at_V(V):
    """构造 V ≥ 12 的三角剖分起点：由 icosa 逐次锥化首个真面，每次 +1 元胞。"""
    if V < 12:
        raise ValueError("V 必须大于等于 12")

    # 从二十面体开始
    net = Icosahedron()

    while net.V() < V:
        # 找到第一个真面
        for face in net.faces():
            if net.face_degree(face) == 3:
                # 锥化该面
                net.cone_face(face)
                break
        else:
            raise RuntimeError("没有找到可锥化的真面")

    return net
