def intersection(net, candidates):
    """§3.5 交集提交判据：候选存活 ⟺ 它的每个角点都接受它。

    按候选汇总被接受的入射数，与角点数相等即存活。
    """
    alive_candidates = []
    for candidate in candidates:
        vertices = net.candidate_vertices(candidate)
        accepted_incoming = {v: 0 for v in vertices}

        for edge in net.candidate_edges(candidate):
            src, dst = net.edge_vertices(edge)
            if dst in accepted_incoming:
                accepted_incoming[dst] += 1

        if all(accepted_incoming[v] == net.vertex_degree(v) for v in vertices):
            alive_candidates.append(candidate)

    return alive_candidates
